 static class LauncherWorkshopRebuild {
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr LoadLibraryEx(string path,IntPtr file,uint flags);
  [DllImport("kernel32.dll",CharSet=CharSet.Ansi)]static extern IntPtr GetProcAddress(IntPtr dll,string name);
  [DllImport("kernel32.dll")]static extern bool FreeLibrary(IntPtr dll);
  [UnmanagedFunctionPointer(CallingConvention.Cdecl)][return:MarshalAs(UnmanagedType.I1)]delegate bool Init();
  [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate void Shutdown();
  [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate IntPtr Interface();
  [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate uint AppId(IntPtr self);
  [UnmanagedFunctionPointer(CallingConvention.Cdecl)][return:MarshalAs(UnmanagedType.I1)]delegate bool LoggedOn(IntPtr self);
  [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate uint Count(IntPtr self,[MarshalAs(UnmanagedType.I1)]bool includeLocallyDisabled);
  [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate uint Items(IntPtr self,[Out,MarshalAs(UnmanagedType.LPArray,SizeParamIndex=2)]ulong[] ids,uint count,[MarshalAs(UnmanagedType.I1)]bool includeLocallyDisabled);
  [UnmanagedFunctionPointer(CallingConvention.Cdecl)][return:MarshalAs(UnmanagedType.I1)]delegate bool InstallInfo(IntPtr self,ulong id,out ulong size,StringBuilder folder,uint capacity,out uint time);
  [UnmanagedFunctionPointer(CallingConvention.Cdecl)][return:MarshalAs(UnmanagedType.I1)]delegate bool DownloadInfo(IntPtr self,ulong id,out ulong done,out ulong total);
  sealed class Snapshot {public ulong[] Ids;public ulong RequiredBytes;}
  static T Function<T>(IntPtr dll,string name)where T:class{IntPtr p=GetProcAddress(dll,name);if(p==IntPtr.Zero)throw new Exception("Steam API 缺少订阅枚举能力："+name+"；未清理任何工坊文件。");return (T)(object)Marshal.GetDelegateForFunctionPointer(p,typeof(T));}
  static void RequireGame(Engine e){LauncherMaintenance.NoReparse(e.Game);string common=Path.GetDirectoryName(e.Game),apps=Path.GetDirectoryName(common);if(!GameDiscovery.IsGameFolder(e.Game)||!string.Equals(Path.GetFileName(common),"common",StringComparison.OrdinalIgnoreCase)||!string.Equals(Path.GetFileName(apps),"steamapps",StringComparison.OrdinalIgnoreCase)||!string.Equals(e.Workshop,Path.GetFullPath(Path.Combine(apps,"workshop","content","108600")),StringComparison.OrdinalIgnoreCase))throw new Exception("工坊重建必须使用 Steam steamapps/common 内的有效游戏安装；未清理文件。");}
  static void RequireOnline(IntPtr dll){IntPtr user=IntPtr.Zero;for(int n=23;n>=19;n--){IntPtr p=GetProcAddress(dll,"SteamAPI_SteamUser_v"+n.ToString("D3"));if(p!=IntPtr.Zero){user=((Interface)Marshal.GetDelegateForFunctionPointer(p,typeof(Interface)))();if(user!=IntPtr.Zero)break;}}if(user==IntPtr.Zero||!Function<LoggedOn>(dll,"SteamAPI_ISteamUser_BLoggedOn")(user))throw new Exception("需要 Steam 在线登录并连接服务后读取完整订阅；未清理文件。");}
  static Snapshot Subscriptions(Engine e){
   e.Guard();RequireGame(e);string library=Path.Combine(e.Game,"steam_api64.dll");LauncherMaintenance.NoReparse(library);if(!Environment.Is64BitProcess||!File.Exists(library))throw new Exception("工坊重建需要游戏自带的 64 位 Steam API。");
   IntPtr dll=LoadLibraryEx(library,IntPtr.Zero,0x1100);if(dll==IntPtr.Zero)throw new Exception("无法加载 Steam API；未清理文件。");bool initialized=false;Shutdown shutdown=null;string oldApp=Environment.GetEnvironmentVariable("SteamAppId"),oldGame=Environment.GetEnvironmentVariable("SteamGameId");
   try{
    Environment.SetEnvironmentVariable("SteamAppId","108600");Environment.SetEnvironmentVariable("SteamGameId","108600");shutdown=Function<Shutdown>(dll,"SteamAPI_Shutdown");
    if(!Function<Init>(dll,GetProcAddress(dll,"SteamAPI_Init")==IntPtr.Zero?"SteamAPI_InitSafe":"SteamAPI_Init")())throw new Exception("Steam 初始化失败；请登录拥有该游戏的账号。未清理文件。");initialized=true;RequireOnline(dll);
    IntPtr utils=Function<Interface>(dll,"SteamAPI_SteamUtils_v010")();if(utils==IntPtr.Zero||Function<AppId>(dll,"SteamAPI_ISteamUtils_GetAppID")(utils)!=108600)throw new Exception("Steam 当前应用身份不是 App108600；未清理文件。");
    IntPtr ugc=Function<Interface>(dll,"SteamAPI_SteamUGC_v021")();if(ugc==IntPtr.Zero)throw new Exception("需要 Steam UGC v021 以确认完整订阅枚举 ABI；未清理文件。");
    foreach(string export in new[]{"SteamAPI_ISteamUGC_DownloadItem","SteamAPI_ISteamUGC_GetItemDownloadInfo","SteamAPI_ISteamUGC_GetItemInstallInfo","SteamAPI_ManualDispatch_Init","SteamAPI_GetHSteamPipe","SteamAPI_ManualDispatch_RunFrame","SteamAPI_ManualDispatch_GetNextCallback","SteamAPI_ManualDispatch_FreeLastCallback","SteamAPI_ISteamUGC_GetItemState","SteamAPI_ISteamUGC_SubscribeItem","SteamAPI_ISteamUtils_IsAPICallCompleted","SteamAPI_ISteamUtils_GetAPICallResult"})if(GetProcAddress(dll,export)==IntPtr.Zero)throw new Exception("Steam 下载接口不可用："+export+"；未清理文件。");
    var count=Function<Count>(dll,"SteamAPI_ISteamUGC_GetNumSubscribedItems");var get=Function<Items>(dll,"SteamAPI_ISteamUGC_GetSubscribedItems");uint number=count(ugc,true);if(number>100000)throw new Exception("订阅数量异常；未清理文件。");
    var ids=new ulong[number];uint returned=number==0?0:get(ugc,ids,number,true);var confirmation=new ulong[number];uint confirmed=number==0?0:get(ugc,confirmation,number,true);
    if(returned!=number||confirmed!=number||count(ugc,true)!=number||!ids.OrderBy(id=>id).SequenceEqual(confirmation.OrderBy(id=>id))||ids.Any(id=>id==0)||ids.Distinct().Count()!=ids.Length)throw new Exception("Steam 订阅列表发生变化或不完整；请重试。未清理文件。");
    ulong required=0;var install=Function<InstallInfo>(dll,"SteamAPI_ISteamUGC_GetItemInstallInfo");var download=Function<DownloadInfo>(dll,"SteamAPI_ISteamUGC_GetItemDownloadInfo");foreach(ulong id in ids){ulong installed=0,done=0,total=0;uint time;bool knownInstall=install(ugc,id,out installed,new StringBuilder(4096),4096,out time),knownDownload=download(ugc,id,out done,out total);ulong size=Math.Max(knownInstall?installed:0,knownDownload?total:0);if(size==0)throw new Exception("无法预估订阅条目 "+id+" 的下载大小；请先在 Steam 下载完成后重试。未清理文件。");required=checked(required+size);}
    RequireOnline(dll);return new Snapshot{Ids=ids,RequiredBytes=required};
   }finally{if(initialized&&shutdown!=null)shutdown();Environment.SetEnvironmentVariable("SteamAppId",oldApp);Environment.SetEnvironmentVariable("SteamGameId",oldGame);FreeLibrary(dll);}
  }
  static void ValidateTree(string root){LauncherMaintenance.NoReparse(root);foreach(string file in Directory.GetFiles(root))LauncherMaintenance.NoReparse(file);foreach(string dir in Directory.GetDirectories(root))ValidateTree(dir);}
  static string[] Targets(Engine e){string root=e.Workshop;LauncherMaintenance.NoReparse(root);if(!Directory.Exists(root))return new string[0];if(Directory.GetFiles(root).Length>0)throw new Exception("App108600 根目录有未知文件；未清理工坊。");var dirs=Directory.GetDirectories(root);foreach(string dir in dirs){ulong id;if(!Regex.IsMatch(Path.GetFileName(dir),@"^[1-9][0-9]*$")||!ulong.TryParse(Path.GetFileName(dir),out id))throw new Exception("工坊目录包含未知名称："+dir+"；未清理。");ValidateTree(dir);}return dirs;}
  static void DeleteTree(Engine e,string dir,CancellationToken cancel){cancel.ThrowIfCancellationRequested();e.Guard();LauncherMaintenance.NoReparse(dir);foreach(string child in Directory.GetDirectories(dir))DeleteTree(e,child,cancel);foreach(string file in Directory.GetFiles(dir)){cancel.ThrowIfCancellationRequested();e.Guard();LauncherMaintenance.NoReparse(file);File.Delete(file);}cancel.ThrowIfCancellationRequested();e.Guard();LauncherMaintenance.NoReparse(dir);Directory.Delete(dir,false);}
  internal static string Apply(Engine e,ulong[] subscribed,Action<ulong[],Action<int,string>,CancellationToken> fetch,Action<int,string> progress,CancellationToken cancel){
   e.Guard();cancel.ThrowIfCancellationRequested();if(subscribed==null||fetch==null||subscribed.Any(id=>id==0)||subscribed.Distinct().Count()!=subscribed.Length)throw new Exception("需要完整的 Steam 订阅快照和官方下载器；未清理工坊。");RequireGame(e);string[] targets=Targets(e);if(subscribed.Length==0&&targets.Length>0)throw new Exception("订阅列表为空但存在工坊缓存；无法确认 Steam 已加载完整订阅，未清理文件。");LauncherMaintenance.NoReparse(e.Data);Directory.CreateDirectory(e.Data);string marker=Path.Combine(e.Data,"workshop-rebuild.pending");LauncherMaintenance.NoReparse(marker);string temporary=marker+"."+Guid.NewGuid().ToString("N")+".tmp";
   try{File.WriteAllText(temporary,new JavaScriptSerializer().Serialize(new{game=e.Game,app=108600,subscribed=subscribed,targets=targets,startedUtc=DateTime.UtcNow.ToString("o")}),new UTF8Encoding(false));if(File.Exists(marker))File.Replace(temporary,marker,null);else File.Move(temporary,marker);}finally{if(File.Exists(temporary))File.Delete(temporary);}
   if(progress!=null)progress(0,"已确认 "+subscribed.Length+" 项订阅；清理 App108600 缓存");
   foreach(string dir in targets){DeleteTree(e,dir,cancel);}cancel.ThrowIfCancellationRequested();if(subscribed.Length>0)fetch(subscribed,progress,cancel);
   foreach(ulong id in subscribed){string dir=Path.Combine(e.Workshop,id.ToString());LauncherMaintenance.NoReparse(dir);if(!Directory.Exists(dir))throw new Exception("工坊重建缺少安装目录："+id);ValidateTree(dir);if(!Directory.EnumerateFiles(dir,"*",SearchOption.AllDirectories).Any())throw new Exception("工坊重建未确认安装文件："+id+"；失败标记保留，启动已阻止。");}
   cancel.ThrowIfCancellationRequested();e.Guard();LauncherMaintenance.NoReparse(marker);File.Delete(marker);if(progress!=null)progress(100,"全部订阅已重新下载并确认文件");return "已重建 App108600 的工坊缓存并重新下载 "+subscribed.Length+" 项订阅；未取消任何订阅，保留工坊清单和其他游戏。";
  }
  internal static string PreflightAndApply(Engine e,ulong[] subscribed,Action preflight,Action<ulong[],Action<int,string>,CancellationToken> fetch,Action<int,string> progress,CancellationToken cancel){cancel.ThrowIfCancellationRequested();if(preflight==null)throw new Exception("缺少工坊容量与 SDK 预检查。");preflight();return Apply(e,subscribed,fetch,progress,cancel);}
  static void Capacity(Engine e,ulong required){RequireGame(e);string[] dirs=Targets(e);ulong reclaim=0;foreach(string dir in dirs)foreach(string file in Directory.EnumerateFiles(dir,"*",SearchOption.AllDirectories)){LauncherMaintenance.NoReparse(file);reclaim=checked(reclaim+(ulong)new FileInfo(file).Length);}var drive=new DriveInfo(Path.GetPathRoot(e.Workshop));ulong usable=checked((ulong)drive.AvailableFreeSpace+reclaim),buffer=Math.Max(1073741824UL,required/10);if(usable<checked(required+buffer))throw new Exception("工坊重建空间不足；需容纳预估下载量并保留至少 1 GiB / 10% 余量。未清理文件。");}
  public static int RunSnapshot(string game,string user,string data){try{var snapshot=Subscriptions(new Engine(game,user,data));Console.WriteLine(new JavaScriptSerializer().Serialize(new{kind="snapshot",app=108600,subscribed=snapshot.Ids,requiredBytes=snapshot.RequiredBytes,nativeSteamLoaded=Process.GetCurrentProcess().Modules.Cast<ProcessModule>().Any(m=>m.ModuleName.Equals("steam_api64.dll",StringComparison.OrdinalIgnoreCase))}));return 0;}catch(Exception x){Console.Error.WriteLine(x.Message);return 1;}}
  public static int Run(string game,string user,string data){var json=new JavaScriptSerializer();try{var e=new Engine(game,user,data);var snapshot=Subscriptions(e);string result=PreflightAndApply(e,snapshot.Ids,()=>Capacity(e,snapshot.RequiredBytes),(requested,p,c)=>{var paths=SteamWorkshop.Fetch(game,requested,p,c,420,false,true);foreach(ulong id in requested){string expected=Path.Combine(e.Workshop,id.ToString());if(!paths.ContainsKey(id)||!string.Equals(Path.GetFullPath(paths[id]).TrimEnd('\\'),Path.GetFullPath(expected).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase))throw new Exception("Steam 返回的工坊路径不属于 App108600："+id);}},(v,t)=>{Console.WriteLine(json.Serialize(new{kind="progress",value=v,text=t}));Console.Out.Flush();},CancellationToken.None);Console.WriteLine(json.Serialize(new{kind="complete",text=result}));return 0;}catch(Exception x){Console.Error.WriteLine(x.Message);return 1;}}
  public static string Start(Engine e,Action<int,string> progress,CancellationToken cancel){
   e.Guard();cancel.ThrowIfCancellationRequested();RequireGame(e);LauncherMaintenance.NoReparse(e.Data);LauncherMaintenance.NoReparse(e.Workshop);var info=new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"--launcher-workshop-rebuild \""+e.Game.TrimEnd('\\')+"\" \""+Path.GetFullPath(e.User).TrimEnd('\\')+"\" \""+Path.GetFullPath(e.Data).TrimEnd('\\')+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};
   using(var process=new Process{StartInfo=info}){string complete=null,protocolError=null;var errors=new StringBuilder();var sync=new object();process.OutputDataReceived+=(sender,args)=>{if(args.Data==null)return;try{var item=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(args.Data);if(Convert.ToString(item["kind"])=="progress"){if(progress!=null)progress(Convert.ToInt32(item["value"]),Convert.ToString(item["text"]));}else if(Convert.ToString(item["kind"])=="complete")lock(sync)complete=Convert.ToString(item["text"]);}catch(Exception x){lock(sync)protocolError=x.Message;}};process.ErrorDataReceived+=(sender,args)=>{if(args.Data!=null)lock(sync){if(errors.Length<65536)errors.AppendLine(args.Data);}};
    process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();try{while(!process.WaitForExit(100)){cancel.ThrowIfCancellationRequested();}process.WaitForExit();}catch{if(!process.HasExited){process.Kill();process.WaitForExit(5000);}throw;}if(process.ExitCode!=0||complete==null||protocolError!=null)throw new Exception("工坊重建未完成；保留失败标记。\r\n"+errors+protocolError);if(File.Exists(Path.Combine(e.Data,"workshop-rebuild.pending")))throw new Exception("工坊重建仍有待处理标记；禁止启动。");return complete;
   }
  }
